{"command":"cat > /tmp/run_checker_messages.py <<'PY'
import subprocess, pathlib, tempfile, os, re, textwrap, shlex

checkers = "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc".split(',')

# Map of checker to file content attempt
# We'll try to use doc snippet as is but add necessary package and imports
# For each checker, we have snippet extracted earlier, we'll try to create valid Go file

docs_dir = pathlib.Path('/tmp/docs')

def get_snippet(checker):
    txt = (docs_dir / f"{checker}.txt").read_text()
    m = re.search(r'Non-compliant code:\n(.*?)\n\nCompliant code:', txt, re.S)
    if not m:
        return None
    snippet = m.group(1).strip()
    return snippet

# Predefined full file templates for each checker that are known to work
templates = {
    "appendAssign": """
package p
type P struct { positives []int; negatives []int }
func Foo(p *P, x int) { p.positives = append(p.negatives, x) }
""",
    "assignOp": """
package p
func foo() { x := 1; x = x * 2; _ = x }
""",
    "captLocal": """
package p
func f(IN int, OUT *int) (ERR error) { return nil }
""",
    "commentFormatting": """
package p
//This is a comment
func foo() {}
""",
    "defaultCaseOrder": """
package p
func foo(x int) {
    switch x {
    case 1:
    default:
    case 2:
    }
}
""",
    "dupArg": """
package p
func foo() { var dst []int; copy(dst, dst) }
""",
    "dupBranchBody": """
package p
func foo(cond bool) {
    if cond {
        println("cond=true")
    } else {
        println("cond=true")
    }
}
""",
    "dupCase": """
package p
func foo(x int, ys []int) {
    switch x {
    case ys[0], ys[1], ys[2], ys[0], ys[4]:
    }
}
""",
    "elseif": """
package p
func foo() {
    if true {
    } else {
        if true {
        }
    }
}
""",
    "exitAfterDefer": """
package p
import "os"
import "log"
func foo(filename string, bad bool) {
    defer os.Remove(filename)
    if bad {
        log.Fatalf("something")
    }
}
""",
    "ifElseChain": """
package p
func foo(cond1, cond2 bool) {
    if cond1 {
    } else if cond2 {
    } else {
    }
    // Actually doc says if cond1 ... else if cond2 ... else ... is ifElseChain? Need 3 branches?
    // Example from doc: if cond1 {} else if cond2 {} else {} -> suggestion to switch
}
""",
    "mapKey": """
package p
func foo() {
    _ = map[string]int{
        "foo": 1,
        "bar ": 2,
    }
}
""",
    "newDeref": """
package p
func foo() { x := *new(bool); _ = x }
""",
    "sloppyLen": """
package p
func foo(arr []int) {
    if len(arr) <= 0 {}
}
""",
    "sloppyTypeAssert": """
package p
import "io"
func f(r io.Reader) interface{} { return r.(interface{}) }
""",
    "switchTrue": """
package p
func foo() { switch true {} }
""",
    "wrapperFunc": """
package p
import "sync"
func foo(wg sync.WaitGroup) { wg.Add(-1) }
""",
    "underef": """
package p
type T struct { field int }
func foo(k *T, a *[]int) {
    (*k).field = 5
    _ = (*a)[0]
}
""",
    "unslice": """
package p
func foo(b []int, values []int) { copy(b[:], values) }
""",
    "valSwap": """
package p
func foo(tmp, x, y *int) { *tmp = *x; *x = *y; *y = *tmp }
""",
    "commentFormatting": """
package p
//This is a comment
func foo() {}
""",
}

# For others, use generic approach: wrap snippet in func with necessary imports guessing

for checker in checkers:
    snippet = get_snippet(checker)
    # Try template if exists
    if checker in templates:
        code = templates[checker].strip() + "\n"
    else:
        # Use snippet wrapped
        # Determine needed imports based on snippet content
        imports = []
        if "strings." in snippet:
            imports.append('"strings"')
        if "regexp." in snippet:
            imports.append('"regexp"')
        if "os." in snippet or "log." in snippet:
            if '"os"' not in imports:
                imports.append('"os"')
            if '"log"' not in imports and "log." in snippet:
                imports.append('"log"')
        if "flag." in snippet:
            imports.append('"flag"')
        if "ast." in snippet:
            imports.append('"go/ast"')
        if "sync." in snippet:
            imports.append('"sync"')
        if "io." in snippet:
            imports.append('"io"')
        if "sort." in snippet:
            imports.append('"sort"')
        if "fmt." in snippet:
            imports.append('"fmt"')
        # Build file
        import_block = ""
        if imports:
            import_block = "import (\n" + "\n".join(imports) + "\n)\n"
        # If snippet starts with // comment (codegenComment), need special handling
        if snippet.strip().startswith("//"):
            # codegenComment expects file header comment
            code = f"// This file was automatically generated by foogen\npackage p\n{snippet}\nfunc dummy(){{}}\n"
            # Actually snippet is "// This file was automatically generated by foogen"
            code = f"{snippet}\npackage p\n{import_block}func foo(){{}}\n"
            # The file must have package after comment? Actually codegenComment checks file header before package.
            # The correct non-compliant is a file starting with "// This file was automatically generated..."
            # We'll create file with that comment at top before package.
            code = f"{snippet}\npackage p\n{import_block}func foo(){{}}\n"
        elif snippet.strip().startswith("func") and not snippet.strip().startswith("func foo"):
            # captLocal etc is already func definition
            code = f"package p\n{import_block}{snippet}\n"
        elif snippet.strip().startswith("package"):
            code = snippet + "\n"
        else:
            # Wrap inside function
            # If snippet contains func definition like "switch ..." etc, wrap appropriately
            if snippet.strip().startswith("switch") or snippet.strip().startswith("if") or snippet.strip().startswith("for"):
                code = f"package p\n{import_block}func foo() {{\n{snippet}\n}}\n"
            else:
                code = f"package p\n{import_block}func foo() {{\n{snippet}\n}}\n"
        # Special handling for some
        if checker == "codegenComment":
            code = "// This file was automatically generated by foogen\npackage p\nfunc foo(){}\n"
        if checker == "deprecatedComment":
            code = "package p\n// deprecated, use FuncNew instead\nfunc FuncOld() int {return 0}\n"
        if checker == "argOrder":
            code = 'package p\nimport "strings"\nfunc foo(userpass string) { _ = strings.HasPrefix("#", userpass) }\n'
        if checker == "badCall":
            code = 'package p\nimport "strings"\nfunc foo(s, from, to string) { _ = strings.Replace(s, from, to, 0) }\n'
        if checker == "badCond":
            code = 'package p\nfunc foo(n int, xs []int) { for i := 0; i > n; i++ { xs[i]=0 } }\n'
        if checker == "caseOrder":
            code = 'package p\nimport "go/ast"\nfunc foo(x ast.Expr) { switch x.(type) { case ast.Expr: println("a"); case *ast.BasicLit: println("b") } }\n'
        if checker == "flagDeref":
            code = 'package p\nimport "flag"\nfunc foo() { b := *flag.Bool("b", false, "b docs"); _=b }\n'
        if checker == "flagName":
            code = 'package p\nimport "flag"\nfunc foo() { b := flag.Bool(" foo ", false, "description"); _=b }\n'
        if checker == "offBy1":
            code = 'package p\nfunc foo(xs []int) { _ = xs[len(xs)] }\n'
        if checker == "regexpMust":
            code = 'package p\nimport "regexp"\nfunc foo() { re, _ := regexp.Compile("const pattern"); _=re }\n'
        if checker == "singleCaseSwitch":
            code = 'package p\nfunc foo(x interface{}) { switch x := x.(type) { case int: println(x) } }\n'
        if checker == "typeSwitchVar":
            code = 'package p\ntype point struct{x,y int}\nfunc foo(v interface{}) int { switch v.(type) { case int: return v.(int); case point: return v.(point).x + v.(point).y; default: return 0 } }\n'
        if checker == "unlambda":
            code = 'package p\nfunc fn(x int) int {return x}\nfunc foo() { _ = func(x int) int { return fn(x) } }\n'
        if checker == "dupSubExpr":
            code = 'package p\nimport "sort"\ntype S struct{v int}\nfunc foo(xs []S) { sort.Slice(xs, func(i, j int) bool { return xs[i].v < xs[i].v }) }\n'
        if checker == "codegenComment":
            code = "// This file was automatically generated by foogen\npackage p\nfunc foo(){}\n"
    # Write to temp
    import tempfile, pathlib, subprocess
    with tempfile.TemporaryDirectory() as td:
        td_path = pathlib.Path(td)
        (td_path / "go.mod").write_text("module p\ngo 1.21\n")
        # Write file
        # For codegenComment, need file named e.g., gen.go? but checker checks file comments
        f_path = td_path / "x.go"
        f_path.write_text(code)
        cmd = ["/workspace/executable", "check", f"-enable={checker}", str(f_path)]
        result = subprocess.run(cmd, capture_output=True, text=True)
        out = result.stderr.strip()
        combined = result.stdout.strip() + result.stderr.strip()
        # Also try with directory if needed
        if not out:
            # try with directory
            cmd2 = ["/workspace/executable", "check", f"-enable={checker}", str(td_path)]
            result2 = subprocess.run(cmd2, capture_output=True, text=True)
            out2 = result2.stderr.strip()
            if out2:
                out = out2
        print(f"== {checker} ==")
        print(code[:500].replace(chr(10),'\\n'))
        print("-->", out[:600] if out else "(no output)")
        print("exit", result.returncode)
        print()

PY
"}

