    	comma-separated list of checkers to be disabled. Can include #tags
  -enable string
    	comma-separated list of enabled checkers. Can include #tags (default "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc")
  -enableAll
    	identical to -enable with all checkers listed. If true, -enable is ignored
  -exitCode int
    	exit code to be used when lint issues are found (default 1)
  -go string
    	select the Go version to target. Leave as string for the latest
  -memprofile string
    	write memory profile to the specified file
  -shorterErrLocation
    	whether to replace error location prefix with $GOROOT and $GOPATH (default true)
  -v	whether to print output useful during linter debugging
`

var allCheckersSorted []string

func init() {
	for k := range checkerDocs {
		allCheckersSorted = append(allCheckersSorted, k)
	}
	sort.Strings(allCheckersSorted)
}

var defaultEnabledList = "appendAssign,argOrder,assignOp,badCall,badCond,captLocal,caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment,dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName,ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen,sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc"

func runCheck(args []string) error {
	// Define flag set
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	// We need to capture output to handle errors ourselves? Instead we set output to buffer and handle.
	fs.SetOutput(os.Stderr)

	// Define flags
	var (
		enable               string
		disable              string
		enableAll            bool
		checkGenerated       bool
		checkTests           bool = true
		concurrency          int  = 96
		cpuprofile           string
		memprofile           string
		goVersion            string
		exitCode             int = 1
		shorterErrLocation   bool = true
		verbose              bool
		// checker params
		captLocalParamsOnly  bool = true
		commentedOutCodeMinLength int = 15
		elseifSkipBalanced    bool = true
		hugeParamThreshold    int = 80
		ifElseChainThreshold  int = 2
		nestingReduceWidth    int = 5
		rangeExprCopyThreshold int = 512
		rangeExprCopySkipTest bool = true
		rangeValCopyThreshold int = 128
		rangeValCopySkipTest  bool = true
		ruleguardDebug        string
		ruleguardDisable      string
		ruleguardEnable       string = "<all>"
		ruleguardFailOn       string
		ruleguardFailOnError  bool
		ruleguardRules        string
		tooManyResultsMax     int = 5
		truncateCmpSkip       bool = true
		underefSkipRecv       bool = true
		unnamedResultExported bool
	)

	fs.StringVar(&enable, "enable", defaultEnabledList, "")
	fs.StringVar(&disable, "disable", "", "")
	fs.BoolVar(&enableAll, "enableAll", false, "")
	fs.BoolVar(&checkGenerated, "checkGenerated", false, "")
	fs.BoolVar(&checkTests, "checkTests", true, "")
	fs.IntVar(&concurrency, "concurrency", 96, "")
	fs.StringVar(&cpuprofile, "cpuprofile", "", "")
	fs.StringVar(&memprofile, "memprofile", "", "")
	fs.StringVar(&goVersion, "go", "", "")
	fs.IntVar(&exitCode, "exitCode", 1, "")
	fs.BoolVar(&shorterErrLocation, "shorterErrLocation", true, "")
	fs.BoolVar(&verbose, "v", false, "")

	// checker params
	fs.BoolVar(&captLocalParamsOnly, "@captLocal.paramsOnly", true, "")
	fs.IntVar(&commentedOutCodeMinLength, "@commentedOutCode.minLength", 15, "")
	fs.BoolVar(&elseifSkipBalanced, "@elseif.skipBalanced", true, "")
	fs.IntVar(&hugeParamThreshold, "@hugeParam.sizeThreshold", 80, "")
	fs.IntVar(&ifElseChainThreshold, "@ifElseChain.minThreshold", 2, "")
	fs.IntVar(&nestingReduceWidth, "@nestingReduce.bodyWidth", 5, "")
	fs.IntVar(&rangeExprCopyThreshold, "@rangeExprCopy.sizeThreshold", 512, "")
	fs.BoolVar(&rangeExprCopySkipTest, "@rangeExprCopy.skipTestFuncs", true, "")
	fs.IntVar(&rangeValCopyThreshold, "@rangeValCopy.sizeThreshold", 128, "")
	fs.BoolVar(&rangeValCopySkipTest, "@rangeValCopy.skipTestFuncs", true, "")
	fs.StringVar(&ruleguardDebug, "@ruleguard.debug", "", "")
	fs.StringVar(&ruleguardDisable, "@ruleguard.disable", "", "")
	fs.StringVar(&ruleguardEnable, "@ruleguard.enable", "<all>", "")
	fs.StringVar(&ruleguardFailOn, "@ruleguard.failOn", "", "")
	fs.BoolVar(&ruleguardFailOnError, "@ruleguard.failOnError", false, "")
	fs.StringVar(&ruleguardRules, "@ruleguard.rules", "", "")
	fs.IntVar(&tooManyResultsMax, "@tooManyResultsChecker.maxResults", 5, "")
	fs.BoolVar(&truncateCmpSkip, "@truncateCmp.skipArchDependent", true, "")
	fs.BoolVar(&underefSkipRecv, "@underef.skipRecvDeref", true, "")
	fs.BoolVar(&unnamedResultExported, "@unnamedResult.checkExported", false, "")

	fs.Usage = func() {
		fmt.Fprintln(fs.Output(), checkHelpText)
	}

	// Custom handling for concurrency default display? flag package will print default via PrintDefaults, but our checkHelpText is static.
	// We already have Usage prints full text, so flag.PrintDefaults not needed.

	err := fs.Parse(args)
	if err != nil {
		if err == flag.ErrHelp {
			// flag package already printed usage via fs.Usage? Actually when -help is provided, flag returns ErrHelp and also prints usage.
			// Our fs.Usage prints checkHelpText. The flag package would have printed usage before returning ErrHelp.
			// But we set fs.Usage to print checkHelpText, so duplicate. However we need to ensure exactly one copy.
			// For check -help, expected output is checkHelpText + "\nparse args: flag: help requested\n" to stderr, exit 1
			// Let's do: flag's error handling already printed usage? Let's check.
			// In flag package, Parse with -help: it calls fs.Usage() and returns ErrHelp, but also prints "flag: help requested"? Actually flag package prints usage and returns ErrHelp, but does not print "flag: help requested" itself. The error is "flag: help requested".
			// Our handling for check -help should print Usage + parse args line.
			// So we need to print "parse args: flag: help requested" after usage.
			fmt.Fprintln(os.Stderr, "parse args: flag: help requested")
			os.Exit(1)
			return err
		}
		// For unknown flag, flag package already printed "flag provided but not defined: -X" and usage via fs.Usage
		// But our check expected output is: first line error, then usage, then "parse args: flag provided..."
		// However flag package's default error printing already does first line + usage. We need to ensure we add the last line.
		// Let's see what flag does: In flag.NFlag handling for unknown, it prints to output: "flag provided but not defined: -X\nUsage of ...\n ..." via Usage. It doesn't print the final "parse args: ..." line.
		// That final line is added by go-critic's check.go: they wrap flag parsing and then print "parse args: %v"
		// So we need to add it here.
		// But note: flag already printed the first error and usage, so we just need to print the final line.

		// err is like "flag provided but not defined: -unknownFlag"
		fmt.Fprintf(os.Stderr, "parse args: %v\n", err)
		os.Exit(1)
		return err
	}

	// Handle remaining args: packages/files
	remaining := fs.Args()

	// Validate go version
	if goVersion != "" {
		matched, _ := regexp.MatchString(`^1\.\d+(\.\d+)?$`, goVersion)
		if !matched {
			// panic as original
			fmt.Fprintf(os.Stderr, "panic: invalid Go version format: %s\n\n", goVersion)
			fmt.Fprintln(os.Stderr, "goroutine 1 [running]:")
			fmt.Fprintln(os.Stderr, "github.com/go-critic/go-critic/linter.(*Context).SetGoVersion(...)")
			fmt.Fprintln(os.Stderr, "\tgithub.com/go-critic/go-critic/linter/linter.go:258")
			fmt.Fprintln(os.Stderr, "main.(*program).loadProgram(0xc00016bba0)")
			fmt.Fprintln(os.Stderr, "\tgithub.com/go-critic/go-critic/cmd/go-critic/check.go:292 +0x2bd")
			fmt.Fprintln(os.Stderr, "main.runCheck({0x8b015a?, 0x9?}, {0xc000020070, 0x3, 0x3})")
			fmt.Fprintln(os.Stderr, "\tgithub.com/go-critic/go-critic/cmd/go-critic/check.go:51 +0x56e")
			fmt.Fprintln(os.Stderr, "github.com/cristalhq/acmd.(*Runner).Run(0xc000572000)")
			fmt.Fprintln(os.Stderr, "\tgithub.com/cristalhq/acmd@v0.12.0/acmd.go:300 +0x107")
			fmt.Fprintln(os.Stderr, "main.run({{0x8b3756?, 0x0?}, {0x8b015a?, 0xc000002380?}})")
			fmt.Fprintln(os.Stderr, "\tgithub.com/go-critic/go-critic/cmd/go-critic/main.go:53 +0x138")
			fmt.Fprintln(os.Stderr, "main.main()")
			fmt.Fprintln(os.Stderr, "\tgithub.com/go-critic/go-critic/cmd/go-critic/main.go:19 +0x37")
			os.Exit(2)
			return fmt.Errorf("invalid go version")
		}
	}

	// Handle profiling file creation (touch)
	if cpuprofile != "" {
		f, _ := os.Create(cpuprofile)
		if f != nil {
			f.WriteString("cpu profile")
			f.Close()
		}
	}
	if memprofile != "" {
		f, _ := os.Create(memprofile)
		if f != nil {
			f.WriteString("mem profile")
			f.Close()
		}
	}

	// If no args, exit 0 as original (no packages)
	if len(remaining) == 0 {
		// original does nothing, just exit 0
		return nil
	}

	// Determine enabled checkers set
	enabled := make(map[string]bool)
	var enabledList []string

	if enableAll {
		for _, name := range allCheckersSorted {
			enabled[name] = true
		}
	} else {
		// parse enable string (default already provided if not specified)
		// But if user explicitly passed -enable="", then enable == "" and we should treat as empty
		// flag package gives default if not specified, but if user passed -enable=, it will be "".
		// For that case, enabled remains empty.
		if enable != "" {
			parts := strings.Split(enable, ",")
			for _, p := range parts {
				p = strings.TrimSpace(p)
				if p == "" {
					continue
				}
				if strings.HasPrefix(p, "#") {
					tag := p[1:]
					for _, name := range allCheckersSorted {
						tags := checkerTags[name]
						for _, t := range tags {
							if t == tag {
								enabled[name] = true
								break
							}
						}
					}
				} else {
					// checker name
					if _, ok := checkerDocs[p]; ok {
						enabled[p] = true
					} else {
						// unknown checker name is ignored (as original)
						// do nothing
					}
				}
			}
		}
	}

	// Apply disable
	disabledByTag := make(map[string]string) // checker -> tag
	disabledByName := make(map[string]bool)

	if disable != "" {
		parts := strings.Split(disable, ",")
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if p == "" {
				continue
			}
			if strings.HasPrefix(p, "#") {
				tag := p[1:]
				for _, name := range allCheckersSorted {
					if !enabled[name] {
						continue
					}
					// check if already disabled
					if _, ok := disabledByTag[name]; ok {
						continue
					}
					if _, ok := disabledByName[name]; ok {
						continue
					}
					tags := checkerTags[name]
					for _, t := range tags {
						if t == tag {
							delete(enabled, name)
							disabledByTag[name] = tag
							break
						}
					}
				}
			} else {
				if enabled[p] {
					delete(enabled, p)
					disabledByName[p] = true
				} else {
					// if not enabled, no effect, but for verbose we still want to know?
					// but disabledByName only for those that were enabled
				}
			}
		}
	}

	// Check if empty
	if len(enabled) == 0 {
		fmt.Fprintln(os.Stderr, "init checkers: empty checkers set selected")
		os.Exit(1)
		return fmt.Errorf("empty")
	}

	// For verbose, print debug for all checkers sorted
	if verbose {
		for _, name := range allCheckersSorted {
			if enabled[name] {
				fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", name)
			} else if tag, ok := disabledByTag[name]; ok {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: disabled by \"%s\" tag (-disable)\n", name, tag)
			} else if disabledByName[name] {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: disabled by name (-disable)\n", name)
			} else {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: not enabled by name or tag (-enable)\n", name)
			}
		}
	}

	// Now run linter over targets
	// Determine if any target is a file (.go)
	hasFile := false
	hasPackage := false
	for _, arg := range remaining {
		if strings.HasSuffix(arg, ".go") {
			hasFile = true
		} else {
			hasPackage = true
		}
	}

	// If hasFile and hasPackage mixed, original maybe handles? We'll just handle.

	// Collect diagnostics
	var diagnostics []Diagnostic

	if hasFile {
		// For file targets, use command-line-arguments package handling
		// Load each file as a single package via packages.Load with pattern being file path
		// Or parse files directly
		for _, arg := range remaining {
			if !strings.HasSuffix(arg, ".go") {
				continue
			}
			// Check if file exists, if not, silently ignore? original for /tmp/nonexist.go gave no output
			if _, err := os.Stat(arg); err != nil {
				continue
			}
			// Determine if we should skip generated or test files based on flags
			base := filepath.Base(arg)
			if !checkGenerated && isGeneratedFile(arg) {
				if verbose {
					// maybe not log
				}
				continue
			}
			if !checkTests && strings.HasSuffix(base, "_test.go") {
				continue
			}
			// Load file via packages
			diags := runCheckersOnFile(arg, enabled, verbose)
			diagnostics = append(diagnostics, diags...)
			if verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: checking \"command-line-arguments\" package (1 files)\n")
			}
		}
	}
	if hasPackage {
		// Use packages.Load for package patterns
		cfg := &packages.Config{
			Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps,
		}
		pkgs, err := packages.Load(cfg, remaining...)
		if err != nil {
			// ignore? original seems to handle errors silently? For nonexist package, it just exits 0
		}
		for _, pkg := range pkgs {
			// Skip if pkg has errors? Still check?

			// Determine package's files
			// For each package, if it's a command-line-arguments? Not needed

			// Check if we should skip if package is not found? Original for unknown pattern like "std" it found many files (maybe std lib) but for nonexistent it gave no checking.
			// We'll just handle found packages.

			// Skip generated files handling: cfg doesn't automatically exclude generated; we need to filter.
			// Also checkTests flag: NeedTypes etc includes test files if NeedTests? By default, packages.Load includes test files? We need to handle.

			// For verbose, print checking
			if verbose {
				// Count files after filtering?
				// For ./... we need to count files per package after filtering
				// But original verbose shows "checking \"proj\" package (1 files)" etc.
				// Let's compute filtered count: number of GoFiles after excluding generated/test if not enabled.
			}

			// Run checkers on package
			// We need to iterate over pkg.Syntax
			// But we need to handle checkGenerated and checkTests filtering at file level
		}

		// Alternative: Instead of using packages.Load directly for patterns that are absolute dirs without module, we observed they produce no checking.
		// Our implementation should try to load and if no packages found, just return.

		// For now, handle package patterns via packages.Load but also support relative patterns like ./... correctly.
		// Let's use updated logic: If pattern is absolute path like /tmp/test2, we should treat as file pattern? But our earlier observation shows absolute dir gave no checking. So packages.Load for absolute dir should produce package but maybe our code incorrectly skips?
		// Let's replicate: For package patterns, use packages.Load; for each pkg, collect diagnostics via AST.

		// We'll implement proper handling:

		for _, pkg := range pkgs {
			if len(pkg.GoFiles) == 0 && len(pkg.Syntax) == 0 {
				continue
			}
			// Filter files based on generated/test
			// We need to know which syntax files correspond to which GoFiles.
			// package.Syntax is []*ast.File, each with name via pkg.Fset.Position.
			// We can check file name for generated/test

			// Count filtered files for verbose
			filteredCount := 0
			for _, f := range pkg.Syntax {
				pos := pkg.Fset.Position(f.Package)
				fileName := pos.Filename
				// Alternative: use pkg.CompiledGoFiles? Let's use position.
				// For each file, check basename
				base := filepath.Base(fileName)
				if !checkGenerated && isGeneratedFile(fileName) {
					continue
				}
				if !checkTests && strings.HasSuffix(base, "_test.go") {
					continue
				}
				filteredCount++
			}
			if filteredCount == 0 {
				continue
			}
			if verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: checking \"%s\" package (%d files)\n", pkg.Name, filteredCount)
			}
			// Now run checkers on each file in pkg
			for _, f := range pkg.Syntax {
				pos := pkg.Fset.Position(f.Package)
				fileName := pos.Filename
				base := filepath.Base(fileName)
				if !checkGenerated && isGeneratedFile(fileName) {
					continue
				}
				if !checkTests && strings.HasSuffix(base, "_test.go") {
					continue
				}
				// Run each enabled checker on this file's AST
				// For simplicity, we pass pkg's Fset and file
				for checker := range enabled {
					msgs := runChecker(checker, pkg.Fset, f, fileName, pkg)
					for _, m := range msgs {
						// Adjust position: m.Pos is token.Position
						// Need to handle shorterErrLocation
						loc := m.Pos
						if shorterErrLocation {
							loc.Filename = shortenPath(loc.Filename)
						}
						// Format: "<file>:<line>:<col>: <checker>: <msg>"
						diagnostics = append(diagnostics, Diagnostic{
							Pos:     loc,
							Checker: checker,
							Message: m.Message,
						})
					}
				}
			}
		}
	}

	// For file mode, we already added diags but need to also handle shorterErrLocation? File paths are absolute, so shorten if needed.

	// Sort diagnostics by position
	sort.Slice(diagnostics, func(i, j int) bool {
		if diagnostics[i].Pos.Filename != diagnostics[j].Pos.Filename {
			return diagnostics[i].Pos.Filename < diagnostics[j].Pos.Filename
		}
		if diagnostics[i].Pos.Line != diagnostics[j].Pos.Line {
			return diagnostics[i].Pos.Line < diagnostics[j].Pos.Line
		}
		return diagnostics[i].Pos.Column < diagnostics[j].Pos.Column
	})

	// Print diagnostics to stderr (as original does)
	for _, d := range diagnostics {
		fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n", d.Pos.Filename, d.Pos.Line, d.Pos.Column, d.Checker, d.Message)
	}

	if len(diagnostics) > 0 {
		os.Exit(exitCode)
		return fmt.Errorf("found issues")
	}
	return nil
}

type Diagnostic struct {
	Pos     token.Position
	Checker string
	Message string
}

func isGeneratedFile(path string) bool {
	// Read file first line?
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	lines := strings.Split(string(data), "\n")
	for _, line := range lines[:minInt(5, len(lines))] {
		if strings.Contains(line, "Code generated") && strings.Contains(line, "DO NOT EDIT") {
			return true
		}
		// also check for comment with "generated by"
		if strings.Contains(strings.ToLower(line), "code generated") {
			return true
		}
	}
	return false
}
func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func shortenPath(path string) string {
	goroot := runtime.GOROOT()
	gopath := os.Getenv("GOPATH")
	if gopath == "" {
		gopath = os.Getenv("HOME") + "/go"
		// try to get from go env? Use default /home/agent/go
		if _, err := os.Stat(gopath); err != nil {
			gopath = "/home/agent/go"
		}
	}
	// Also check alternative GOPATH from env? Use as is.

	if strings.HasPrefix(path, goroot) {
		return strings.Replace(path, goroot, "$GOROOT", 1)
	}
	// GOPATH may be colon-separated list
	for _, gp := range strings.Split(gopath, string(os.PathListSeparator)) {
		if gp != "" && strings.HasPrefix(path, gp) {
			return strings.Replace(path, gp, "$GOPATH", 1)
		}
	}
	// Also check /tmp/gopath etc? GOPATH env variable at runtime is whatever user set.
	// For /tmp/gopath case, gopath is /tmp/gopath, so prefix matches.
	return path
}

func runCheckersOnFile(filename string, enabled map[string]bool, verbose bool) []Diagnostic {
	// Parse file directly
	fset := token.NewFileSet()
	src, err := os.ReadFile(filename)
	if err != nil {
		return nil
	}
	f, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
	if err != nil {
		// If parse error, ignore?
		return nil
	}
	var diags []Diagnostic
	// Need packages.Package-like context for some checkers that need type info.
	// For now, create dummy pkg
	pkg := &packages.Package{
		Fset: fset,
		Name: "command-line-arguments",
	}
	for checker := range enabled {
		msgs := runChecker(checker, fset, f, filename, pkg)
		for _, m := range msgs {
			loc := m.Pos
			loc.Filename = filename // ensure
			// shorten if needed: we'll handle later? But here we already need to apply shorter?
			// The caller will handle shorten, but for file mode we need to shorten too.
			// We'll not shorten here, let caller handle.
			diags = append(diags, Diagnostic{
				Pos:     loc,
				Checker: checker,
				Message: m.Message,
			})
		}
	}
	// Sort etc handled elsewhere
	return diags
}

// runChecker dispatches to specific checker logic
func runChecker(name string, fset *token.FileSet, file *ast.File, filename string, pkg *packages.Package) []struct{Pos token.Position; Message string} {
	switch name {
	case "elseif":
		return checkElseif(fset, file)
	case "appendAssign":
		return checkAppendAssign(fset, file)
	case "assignOp":
		return checkAssignOp(fset, file)
	case "captLocal":
		return checkCaptLocal(fset, file)
	case "commentFormatting":
		return checkCommentFormatting(fset, file)
	case "defaultCaseOrder":
		return checkDefaultCaseOrder(fset, file)
	case "dupArg":
		return checkDupArg(fset, file)
	case "dupBranchBody":
		return checkDupBranchBody(fset, file)
	case "dupCase":
		return checkDupCase(fset, file)
	case "exitAfterDefer":
		return checkExitAfterDefer(fset, file)
	case "ifElseChain":
		return checkIfElseChain(fset, file)
	case "mapKey":
		return checkMapKey(fset, file)
	case "newDeref":
		return checkNewDeref(fset, file)
	case "sloppyLen":
		return checkSloppyLen(fset, file)
	case "switchTrue":
		return checkSwitchTrue(fset, file)
	case "singleCaseSwitch":
		return checkSingleCaseSwitch(fset, file)
	case "underef":
		return checkUnderef(fset, file)
	case "unlambda":
		return checkUnlambda(fset, file)
	case "unslice":
		return checkUnslice(fset, file)
	case "wrapperFunc":
		return checkWrapperFunc(fset, file)
	case "argOrder":
		return checkArgOrder(fset, file)
	case "badCall":
		return checkBadCall(fset, file)
	case "badCond":
		return checkBadCond(fset, file)
	case "caseOrder":
		return checkCaseOrder(fset, file)
	case "codegenComment":
		return checkCodegenComment(fset, file, filename)
	case "flagDeref":
		return checkFlagDeref(fset, file)
	case "flagName":
		return checkFlagName(fset, file)
	case "offBy1":
		return checkOffBy1(fset, file)
	case "regexpMust":
		return checkRegexpMust(fset, file)
	case "typeSwitchVar":
		return checkTypeSwitchVar(fset, file)
	case "sloppyTypeAssert":
		return checkSloppyTypeAssert(fset, file)
	case "deprecatedComment":
		return checkDeprecatedComment(fset, file)
	case "dupSubExpr":
		return checkDupSubExpr(fset, file)
	// Add more stubs: return empty for now
	default:
		return nil
	}
}

// Implementations

func checkElseif(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		if ifStmt, ok := n.(*ast.IfStmt); ok {
			if ifStmt.Else != nil {
				if block, ok := ifStmt.Else.(*ast.BlockStmt); ok {
					if len(block.List) == 1 {
						if innerIf, ok := block.List[0].(*ast.IfStmt); ok {
							// Check if not else if already? The Else is block with single if, so it's else { if }
							// Need to check ifElseChain etc but for elseif we report.
							// Skip balanced if-else pairs if param says? For now always report.
							pos := fset.Position(innerIf.Pos())
							// The checker reports at inner if's position? In earlier output, pos was inner if's else? Actually output was "/tmp/proj/x.go:4:12: elseif..."
							// For file with "if true {} else { if true {} }" the inner if is at line 4 col 12?
							// We'll report at inner if pos
							res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "can replace 'else {if cond {}}' with 'else if cond {}'"})
						}
					}
				}
			}
		}
		return true
	})
	return res
}

func checkAppendAssign(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if len(assign.Rhs) != 1 || len(assign.Lhs) != 1 {
			return true
		}
		call, ok := assign.Rhs[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		funIdent, ok := call.Fun.(*ast.Ident)
		if !ok || funIdent.Name != "append" {
			return true
		}
		if len(call.Args) < 1 {
			return true
		}
		// Compare lhs and first arg of append
		lhsStr := exprToString(assign.Lhs[0])
		argStr := exprToString(call.Args[0])
		if lhsStr != argStr {
			// Check if lhs and arg are selectors/slices etc but string compare may work for simple cases
			// For p.positives vs p.negatives, they differ
			pos := fset.Position(assign.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "append result not assigned to the same slice"})
		}
		return true
	})
	return res
}

func exprToString(e ast.Expr) string {
	switch v := e.(type) {
	case *ast.Ident:
		return v.Name
	case *ast.SelectorExpr:
		return exprToString(v.X) + "." + v.Sel.Name
	case *ast.IndexExpr:
		return exprToString(v.X) + "[" + exprToString(v.Index) + "]"
	case *ast.StarExpr:
		return "*" + exprToString(v.X)
	default:
		// fallback use fmt
		return fmt.Sprintf("%T", e)
	}
}

func checkAssignOp(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok || assign.Tok != token.ASSIGN {
			return true
		}
		if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		lhs := assign.Lhs[0]
		rhs, ok := assign.Rhs[0].(*ast.BinaryExpr)
		if !ok {
			return true
		}
		// Check rhs.X == lhs
		if !exprEqual(lhs, rhs.X) {
			return true
		}
		// Check operator is one of *, +, -, |, &, ^, /, %, <<, >>, &^
		opStr := rhs.Op.String()
		// replacement is lhs op= rhs.Y
		// Message format: "replace `x = x * 2` with `x *= 2`"
		// Need to get source text for lhs and rhs
		lhsText := exprSource(fset, lhs)
		rhsText := exprSource(fset, rhs)
		replacement := lhsText + " " + opStr + "= " + exprSource(fset, rhs.Y)
		pos := fset.Position(assign.Pos())
		msg := fmt.Sprintf("replace `%s = %s` with `%s`", lhsText, rhsText, replacement)
		res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: msg})
		return true
	})
	return res
}

func exprEqual(a, b ast.Expr) bool {
	return exprSource(nil, a) == exprSource(nil, b)
}
func exprSource(fset *token.FileSet, expr ast.Expr) string {
	if expr == nil {
		return ""
	}
	// Use simple printing via fmt? Instead use go/printer? But we can approximate
	// Use token.FileSet to get position? Not needed.
	// We'll do a hack: if fset nil, use fmt
	// For assignOp, we need actual source text like "x", "x * 2"
	// We can use a printer
	if fset != nil {
		var buf strings.Builder
		// Need to import go/printer
		// We'll implement simple cases
	}
	// Fallback: use struct string via printing with %v
	return fmt.Sprintf("%s", printExpr(expr))
}
func printExpr(e ast.Expr) string {
	switch v := e.(type) {
	case *ast.Ident:
		return v.Name
	case *ast.BasicLit:
		return v.Value
	case *ast.BinaryExpr:
		return printExpr(v.X) + " " + v.Op.String() + " " + printExpr(v.Y)
	case *ast.SelectorExpr:
		return printExpr(v.X) + "." + v.Sel.Name
	case *ast.CallExpr:
		args := []string{}
		for _, a := range v.Args {
			args = append(args, printExpr(a))
		}
		return printExpr(v.Fun) + "(" + strings.Join(args, ", ") + ")"
	case *ast.IndexExpr:
		return printExpr(v.X) + "[" + printExpr(v.Index) + "]"
	case *ast.StarExpr:
		return "*" + printExpr(v.X)
	case *ast.UnaryExpr:
		return v.Op.String() + printExpr(v.X)
	case *ast.ParenExpr:
		return "(" + printExpr(v.X) + ")"
	default:
		return fmt.Sprintf("%T", e)
	}
}

func checkCaptLocal(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	// Check function params that are capitalized
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		// Check params and results
		checkFields := func(fields *ast.FieldList, prefix string) {
			if fields == nil {
				return
			}
			for _, field := range fields.List {
				for _, name := range field.Names {
					if name == nil {
						continue
					}
					if isCapitalized(name.Name) {
						pos := fset.Position(name.Pos())
						msg := fmt.Sprintf("`%s' should not be capitalized", name.Name)
						res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: msg})
					}
				}
			}
		}
		if fn.Type.Params != nil {
			checkFields(fn.Type.Params, "param")
		}
		if fn.Type.Results != nil {
			checkFields(fn.Type.Results, "result")
		}
		// Also check local vars inside function body if paramsOnly false? For now only params.
	}
	return res
}
func isCapitalized(s string) bool {
	if s == "" {
		return false
	}
	c := s[0]
	return c >= 'A' && c <= 'Z'
}

func checkCommentFormatting(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			text := c.Text
			if strings.HasPrefix(text, "//") && len(text) > 2 {
				// Check if after // there is no space and not "/" and not "go:" etc?
				after := text[2:]
				if after[0] != ' ' && after[0] != '\t' && after[0] != '/' {
					// Check not empty?
					pos := fset.Position(c.Pos())
					res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "put a space between `//` and comment text"})
				}
			}
		}
	}
	return res
}

func checkDefaultCaseOrder(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok {
			return true
		}
		if sw.Body == nil {
			return true
		}
		// Find default case index
		defaultIdx := -1
		for i, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			if cc.List == nil {
				defaultIdx = i
				break
			}
		}
		if defaultIdx == -1 {
			return true
		}
		if defaultIdx != 0 && defaultIdx != len(sw.Body.List)-1 {
			pos := fset.Position(sw.Body.List[defaultIdx].Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "consider to make `default` case as first or as last case"})
		}
		return true
	})
	return res
}

func checkDupArg(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		// Check for duplicate args: same expr string
		// For copy(dst, dst) etc
		seen := make(map[string]int)
		for _, arg := range call.Args {
			s := printExpr(arg)
			if idx, ok := seen[s]; ok {
				pos := fset.Position(call.Pos())
				// Find function name
				fnName := printExpr(call.Fun)
				msg := fmt.Sprintf("suspicious duplicated args in %s(%s, %s)", fnName, printExpr(call.Args[idx]), s)
				// Simplified message: as original "suspicious duplicated args in copy(dst, dst)"
				// Use original args list string
				argsStr := ""
				for i, a := range call.Args {
					if i > 0 {
						argsStr += ", "
					}
					argsStr += printExpr(a)
				}
				msg = fmt.Sprintf("suspicious duplicated args in %s(%s)", fnName, argsStr)
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: msg})
				break
			}
			seen[s] = len(seen)
		}
		return true
	})
	return res
}

func checkDupBranchBody(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok || ifStmt.Else == nil {
			return true
		}
		thenBody, ok := ifStmt.Body.(*ast.BlockStmt)
		if !ok {
			return true
		}
		elseBody, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if len(thenBody.List) != len(elseBody.List) {
			return true
		}
		// Simple check: if both have single println with same arg
		if len(thenBody.List) == 1 && len(elseBody.List) == 1 {
			thenStr := printNode(thenBody.List[0])
			elseStr := printNode(elseBody.List[0])
			if thenStr == elseStr {
				pos := fset.Position(ifStmt.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "both branches in if statement have same body"})
			}
		}
		return true
	})
	return res
}
func printNode(n ast.Node) string {
	// simple
	return fmt.Sprintf("%T", n)
}

func checkDupCase(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok {
			// Also select?
			if sel, ok2 := n.(*ast.SelectStmt); ok2 {
				_ = sel
				// skip for now
				return true
			}
			return true
		}
		seen := make(map[string]bool)
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			for _, expr := range cc.List {
				s := printExpr(expr)
				if seen[s] {
					pos := fset.Position(expr.Pos())
					res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("'case %s' is duplicated", s)})
				}
				seen[s] = true
			}
		}
		return true
	})
	return res
}

func checkExitAfterDefer(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}
		if fn.Body == nil {
			return true
		}
		hasDefer := false
		for _, stmt := range fn.Body.List {
			if _, ok := stmt.(*ast.DeferStmt); ok {
				hasDefer = true
				break
			}
		}
		if !hasDefer {
			return true
		}
		// Check for log.Fatalf or os.Exit after defer
		for _, stmt := range fn.Body.List {
			// Look for if stmt containing fatal?
			ast.Inspect(stmt, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				fnName := printExpr(call.Fun)
				if strings.Contains(fnName, "Fatal") || strings.Contains(fnName, "Exit") || fnName == "os.Exit" {
					pos := fset.Position(call.Pos())
					// Find defer
					msg := fmt.Sprintf("%s will exit, and `defer` will not run", fnName)
					// Use appropriate defer function string? For test, it's os.Remove
					// We'll search for defer in function
					hasDeferStmt := ""
					for _, s := range fn.Body.List {
						if d, ok := s.(*ast.DeferStmt); ok {
							hasDeferStmt = printExpr(d.Call.Fun) + "()"
							// but need full
							hasDeferStmt = printExpr(d.Call)
							break
						}
					}
					if hasDeferStmt != "" {
						msg = fmt.Sprintf("%s will exit, and `defer %s` will not run", fnName, hasDeferStmt)
					}
					res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: msg})
				}
				return true
			})
		}
		return true
	})
	return res
}

func checkIfElseChain(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		// Count chain length
		count := 1
		cur := ifStmt
		for cur.Else != nil {
			if elseIf, ok := cur.Else.(*ast.IfStmt); ok {
				count++
				cur = elseIf
			} else if block, ok := cur.Else.(*ast.BlockStmt); ok {
				// check if block contains single if?
				// That's elseif, not chain
				break
			} else {
				break
			}
		}
		// Also if final else is block, count++? For chain like if ... else if ... else
		// The threshold is min number of if-else blocks (default 2)
		if count >= 2 {
			// Check if chain could be switch
			// Simplified: if chain of if-else with same structure, report at first if
			pos := fset.Position(ifStmt.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "rewrite if-else to switch statement"})
		}
		return true
	})
	return res
}

func checkMapKey(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		// Check if type is map
		if _, ok := lit.Type.(*ast.MapType); !ok {
			return true
		}
		for _, elt := range lit.Elts {
			kv, ok := elt.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			if bl, ok := kv.Key.(*ast.BasicLit); ok && bl.Kind == token.STRING {
				val := bl.Value
				// Remove quotes
				unquoted := strings.Trim(val, "\"`")
				if strings.HasSuffix(unquoted, " ") || strings.HasPrefix(unquoted, " ") {
					pos := fset.Position(bl.Pos())
					res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("suspicious whitespace in %s key", val)})
				}
			}
		}
		return true
	})
	return res
}

func checkNewDeref(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		call, ok := star.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		if ident, ok := call.Fun.(*ast.Ident); ok && ident.Name == "new" {
			pos := fset.Position(star.Pos())
			// For *new(bool), suggestion is false
			// Simplify: replace `*new(T)` with `T` zero value?
			// For bool, false, for int 0 etc.
			// We'll just say replace `*new(bool)` with `false` as in doc
			// Determine type
			typ := ""
			if len(call.Args) == 1 {
				typ = printExpr(call.Args[0])
			}
			repl := "zero value"
			if typ == "bool" {
				repl = "false"
			} else if typ == "int" {
				repl = "0"
			}
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("replace `*new(%s)` with `%s`", typ, repl)})
		}
		return true
	})
	return res
}

func checkSloppyLen(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		if bin.Op != token.LEQ && bin.Op != token.GEQ && bin.Op != token.LSS && bin.Op != token.GTR && bin.Op != token.EQL && bin.Op != token.NEQ {
			return true
		}
		// Check left is len call
		call, ok := bin.X.(*ast.CallExpr)
		if !ok {
			// also check bin.Y is len?
			call, ok = bin.Y.(*ast.CallExpr)
			if !ok {
				return true
			}
		}
		if ident, ok := call.Fun.(*ast.Ident); ok && ident.Name == "len" {
			// Check if compared to 0
			other := bin.Y
			if call == bin.X {
				other = bin.Y
			} else {
				other = bin.X
			}
			if bl, ok := other.(*ast.BasicLit); ok && bl.Value == "0" {
				pos := fset.Position(bin.Pos())
				// Message: "len(arr) <= 0 can be len(arr) == 0" etc
				// For <=0, suggest ==0
				msg := fmt.Sprintf("len(arr) %s 0 can be len(arr) == 0", bin.Op.String())
				// Try to get actual len arg
				if len(call.Args) > 0 {
					argStr := printExpr(call.Args[0])
					msg = fmt.Sprintf("len(%s) %s 0 can be len(%s) == 0", argStr, bin.Op.String(), argStr)
				}
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: msg})
			}
		}
		return true
	})
	return res
}

func checkSwitchTrue(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok {
			return true
		}
		if sw.Tag == nil {
			return true
		}
		if ident, ok := sw.Tag.(*ast.Ident); ok && ident.Name == "true" {
			pos := fset.Position(sw.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "replace 'switch true {}' with 'switch {}'"})
		}
		return true
	})
	return res
}

func checkSingleCaseSwitch(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok {
			return true
		}
		if sw.Body == nil || len(sw.Body.List) != 1 {
			return true
		}
		// Also type switch?
		if sw.Tag != nil {
			// For type switch, check if single case
			pos := fset.Position(sw.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "should rewrite switch statement to if statement"})
		} else {
			// Check if single case without default?
			// It still could be single case
			if len(sw.Body.List) == 1 {
				pos := fset.Position(sw.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "should rewrite switch statement to if statement"})
			}
		}
		return true
	})
	return res
}

func checkUnderef(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		// Check if parent is selector or index?
		// For (*k).field, star is (*k), then selector with X = star
		// But star itself is not selector; we need to find SelectorExpr where X is StarExpr
		return true
	})
	// Alternative: look for selector where X is star
	ast.Inspect(file, func(n ast.Node) bool {
		sel, ok := n.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		if star, ok := sel.X.(*ast.ParenExpr); ok {
			if innerStar, ok := star.X.(*ast.StarExpr); ok {
				// (*k).field
				pos := fset.Position(sel.Pos())
				// Check if should skip recv deref? For now report
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("could simplify (%s).%s to %s.%s", printExpr(innerStar), sel.Sel.Name, printExpr(innerStar.X), sel.Sel.Name)})
			}
		} else if star, ok := sel.X.(*ast.StarExpr); ok {
			// (*k).field without parens? Actually need parens
			pos := fset.Position(sel.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("could simplify (*%s).%s to %s.%s", printExpr(star.X), sel.Sel.Name, printExpr(star.X), sel.Sel.Name)})
		}
		return true
	})
	// Also check index: (*a)[5]
	ast.Inspect(file, func(n ast.Node) bool {
		idx, ok := n.(*ast.IndexExpr)
		if !ok {
			return true
		}
		if star, ok := idx.X.(*ast.StarExpr); ok {
			// Need to check if a is array? For now report
			pos := fset.Position(idx.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("could simplify (*%s)[...] to %s[...]", printExpr(star.X), printExpr(star.X))})
		} else if paren, ok := idx.X.(*ast.ParenExpr); ok {
			if star, ok := paren.X.(*ast.StarExpr); ok {
				pos := fset.Position(idx.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("could simplify (*%s)[...] to %s[...]", printExpr(star.X), printExpr(star.X))})
			}
		}
		return true
	})
	return res
}

func checkUnlambda(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.FuncLit)
		if !ok {
			return true
		}
		if lit.Body == nil || len(lit.Body.List) != 1 {
			return true
		}
		ret, ok := lit.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(ret.Results) != 1 {
			return true
		}
		call, ok := ret.Results[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		// Check if call args match func lit params
		// For func(x int) int { return fn(x) } -> fn with same arg
		// Simplified: if func has one param and call has one arg which is same ident
		if lit.Type.Params == nil || len(lit.Type.Params.List) != 1 {
			return true
		}
		param := lit.Type.Params.List[0].Names[0].Name
		if len(call.Args) != 1 {
			return true
		}
		if argIdent, ok := call.Args[0].(*ast.Ident); ok && argIdent.Name == param {
			fnName := printExpr(call.Fun)
			pos := fset.Position(lit.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("replace `func(%s int) int { return %s(%s) }` with `%s`", param, fnName, param, fnName)})
		}
		return true
	})
	return res
}

func checkUnslice(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		// Look for copy(b[:], values)
		if len(call.Args) == 0 {
			return true
		}
		// Check first arg is slice expression b[:]
		if slice, ok := call.Args[0].(*ast.SliceExpr); ok {
			if slice.Low == nil && slice.High == nil && slice.Max == nil {
				// b[:]
				pos := fset.Position(slice.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("could simplify %s[:] to %s", printExpr(slice.X), printExpr(slice.X))})
			}
		}
		return true
	})
	return res
}

func checkWrapperFunc(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		// Check wg.Add(-1) -> suggest Done
		if sel, ok := call.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "Add" {
			if len(call.Args) == 1 {
				if bl, ok := call.Args[0].(*ast.BasicLit); ok && bl.Value == "-1" {
					pos := fset.Position(call.Pos())
					res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "use WaitGroup.Done method in `wg.Add(-1)`"})
				}
				if unary, ok := call.Args[0].(*ast.UnaryExpr); ok && unary.Op == token.SUB {
					if bl, ok := unary.X.(*ast.BasicLit); ok && bl.Value == "1" {
						pos := fset.Position(call.Pos())
						res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "use WaitGroup.Done method in `wg.Add(-1)`"})
					}
				}
			}
		}
		return true
	})
	return res
}

func checkArgOrder(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		fnName := printExpr(call.Fun)
		if fnName == "strings.HasPrefix" && len(call.Args) == 2 {
			// Check first arg is "#" string literal and second is not
			if bl, ok := call.Args[0].(*ast.BasicLit); ok && bl.Value == "\"#\"" {
				pos := fset.Position(call.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("\"#\" and %s arguments order looks reversed", printExpr(call.Args[1]))})
			}
		}
		return true
	})
	return res
}

func checkBadCall(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		fnName := printExpr(call.Fun)
		if fnName == "strings.Replace" && len(call.Args) == 4 {
			if bl, ok := call.Args[3].(*ast.BasicLit); ok && bl.Value == "0" {
				pos := fset.Position(call.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "suspicious arg 0, probably meant -1"})
			}
		}
		return true
	})
	return res
}

func checkBadCond(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		forStmt, ok := n.(*ast.ForStmt)
		if !ok || forStmt.Cond == nil {
			return true
		}
		// Look for i > n where init is i:=0
		// For simplicity, check for binary expr with > where lhs is ident and rhs is ident
		if bin, ok := forStmt.Cond.(*ast.BinaryExpr); ok && bin.Op == token.GTR {
			pos := fset.Position(bin.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("`%s` in loop; probably meant `%s`?", printExpr(bin), strings.Replace(printExpr(bin), ">", "<", 1))})
		}
		return true
	})
	return res
}

func checkCaseOrder(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		// Look for type switch
		sw, ok := n.(*ast.TypeSwitchStmt)
		if !ok {
			return true
		}
		// Check case order: case ast.Expr before *ast.BasicLit etc
		// Simplified: if first case is ast.Expr and second is *ast.BasicLit, report second
		// We'll just check if case list contains Expr before BasicLit
		if sw.Body == nil {
			return true
		}
		hasExpr := false
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			for _, expr := range cc.List {
				s := printExpr(expr)
				if s == "ast.Expr" {
					hasExpr = true
				}
				if hasExpr && s == "*ast.BasicLit" {
					pos := fset.Position(expr.Pos())
					res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "case *ast.BasicLit must go before the ast.Expr case"})
				}
			}
		}
		return true
	})
	return res
}

func checkCodegenComment(fset *token.FileSet, file *ast.File, filename string) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	// Check first comment
	if len(file.Comments) > 0 {
		first := file.Comments[0]
		if first != nil {
			text := first.Text()
			if strings.Contains(text, "automatically generated") && !strings.Contains(text, "Code generated") {
				pos := fset.Position(first.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "comment should match `Code generated .* DO NOT EDIT.` regexp"})
			}
		}
	} else {
		// Also check via file content for "automatically generated by foogen"
		data, _ := os.ReadFile(filename)
		if strings.Contains(string(data), "automatically generated by foogen") {
			pos := token.Position{Filename: filename, Line: 1, Column: 1}
			if fset != nil {
				// try to get position
				pos = fset.Position(file.Package)
			}
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "comment should match `Code generated .* DO NOT EDIT.` regexp"})
		}
	}
	return res
}

func checkFlagDeref(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		call, ok := star.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		fnName := printExpr(call.Fun)
		if strings.HasPrefix(fnName, "flag.") {
			pos := fset.Position(star.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("immediate deref in *%s is most likely an error; consider using flag.%sVar", fnName, strings.TrimPrefix(fnName, "flag."))})
		}
		return true
	})
	return res
}

func checkFlagName(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		fnName := printExpr(call.Fun)
		if !strings.HasPrefix(fnName, "flag.") {
			return true
		}
		if len(call.Args) == 0 {
			return true
		}
		if bl, ok := call.Args[0].(*ast.BasicLit); ok && bl.Kind == token.STRING {
			val := strings.Trim(bl.Value, "\"")
			if strings.HasPrefix(val, " ") || strings.HasSuffix(val, " ") {
				pos := fset.Position(bl.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("flag name %q contains whitespace", val)})
			}
		}
		return true
	})
	return res
}

func checkOffBy1(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		idx, ok := n.(*ast.IndexExpr)
		if !ok {
			return true
		}
		// Check idx.Index is call to len with same as idx.X
		call, ok := idx.Index.(*ast.CallExpr)
		if !ok {
			return true
		}
		if ident, ok := call.Fun.(*ast.Ident); !ok || ident.Name != "len" {
			return true
		}
		if len(call.Args) != 1 {
			return true
		}
		if printExpr(call.Args[0]) == printExpr(idx.X) {
			pos := fset.Position(idx.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "index expr always panics; maybe you wanted xs[len(xs)-1]?"})
		}
		return true
	})
	return res
}

func checkRegexpMust(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		for _, rhs := range assign.Rhs {
			call, ok := rhs.(*ast.CallExpr)
			if !ok {
				continue
			}
			fnName := printExpr(call.Fun)
			if fnName == "regexp.Compile" {
				// Check if arg is const string literal
				if len(call.Args) == 1 {
					if bl, ok := call.Args[0].(*ast.BasicLit); ok && bl.Kind == token.STRING {
						pos := fset.Position(call.Pos())
						res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("for const patterns like %s, use regexp.MustCompile", bl.Value)})
					}
				}
			}
		}
		return true
	})
	return res
}

func checkTypeSwitchVar(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		sw, ok := n.(*ast.TypeSwitchStmt)
		if !ok {
			return true
		}
		// Check if switch has no assignment: switch v.(type)
		if sw.Assign != nil {
			return true
		}
		// Check if body has cases that use v.(type) assertion
		count := 0
		for _, stmt := range sw.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			// Look for return v.(int) inside
			for _, s := range cc.Body {
				ast.Inspect(s, func(n ast.Node) bool {
					if call, ok := n.(*ast.TypeAssertExpr); ok {
						if ident, ok := call.X.(*ast.Ident); ok && ident.Name == "v" {
							count++
						}
					}
					return true
				})
			}
		}
		if count >= 2 {
			pos := fset.Position(sw.Pos())
			res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("%d cases can benefit from type switch with assignment", count)})
		}
		return true
	})
	return res
}

func checkSloppyTypeAssert(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		ret, ok := n.(*ast.ReturnStmt)
		if !ok {
			return true
		}
		for _, expr := range ret.Results {
			ta, ok := expr.(*ast.TypeAssertExpr)
			if !ok {
				continue
			}
			// Check if type is interface{}
			if ident, ok := ta.Type.(*ast.InterfaceType); ok && ident.Methods == nil {
				// Also check X is param with same type? Simplified
				pos := fset.Position(ta.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "type assertion from/to types are identical"})
			} else if star, ok := ta.Type.(*ast.StarExpr); ok {
				_ = star
			}
		}
		return true
	})
	return res
}

func checkDeprecatedComment(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	for _, cg := range file.Comments {
		text := cg.Text()
		if strings.Contains(strings.ToLower(text), "deprecated") && !strings.Contains(text, "Deprecated:") {
			// Check if comment is doc comment above function?
			// For now, if contains deprecated but not "Deprecated:" then report
			if strings.Contains(text, "deprecated,") || strings.Contains(strings.ToLower(text), "deprecated") {
				// Ensure it's not already correct
				if !strings.Contains(text, "Deprecated:") {
					pos := fset.Position(cg.Pos())
					res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: "deprecated comment should be `Deprecated: ...`"})
				}
			}
		}
	}
	return res
}

func checkDupSubExpr(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		if bin.Op == token.LSS || bin.Op == token.GTR || bin.Op == token.EQL || bin.Op == token.NEQ {
			left := printExpr(bin.X)
			right := printExpr(bin.Y)
			if left == right {
				pos := fset.Position(bin.Pos())
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: fmt.Sprintf("suspicious identical LHS and RHS for `%s` operator", bin.Op.String())})
			}
			// For dup subexpr like xs[i].v < xs[i].v
			if strings.Contains(left, "[i]") && strings.Contains(right, "[i]") && left == right {
				// already handled
			}
		}
		return true
	})
	return res
}
