	fs.IntVar(&nestingReduceWidth, "@nestingReduce.bodyWidth", 5, "")
	fs.IntVar(&rangeExprCopyThreshold, "@rangeExprCopy.sizeThreshold", 512, "")
	fs.BoolVar(&rangeExprCopySkipTest, "@rangeExprCopy.skipTestFuncs", true, "")
	fs.IntVar(&rangeValCopyThreshold, "@rangeValCopy.sizeThreshold", 128, "")
	fs.BoolVar(&rangeValCopySkipTest, "@rangeValCopy.skipTestFuncs", true, "")
	fs.StringVar(&ruleguardDebug, "@ruleguard.debug", "", "")
	fs.StringVar(&ruleguardDisable, "@ruleguard.disable", "", "")
	fs.StringVar(&ruleguardEnable, "@ruleguard.enable", "<all>", "")
	fs.StringVar(&ruleguardFailOn, "@ruleguard.failOn", "", "")
	fs.BoolVar(&ruleguardFailOnError, "@ruleguard.failOnError", false, "")
	fs.StringVar(&ruleguardRules, "@ruleguard.rules", "", "")
	fs.IntVar(&tooManyResultsMax, "@tooManyResultsChecker.maxResults", 5, "")
	fs.BoolVar(&truncateCmpSkip, "@truncateCmp.skipArchDependent", true, "")
	fs.BoolVar(&underefSkipRecv, "@underef.skipRecvDeref", true, "")
	fs.BoolVar(&unnamedResultExported, "@unnamedResult.checkExported", false, "")

	fs.Usage = func() {
		fmt.Fprintln(fs.Output(), checkHelpText)
	}

	// Custom handling for concurrency default display? flag package will print default via PrintDefaults, but our checkHelpText is static.
	// We already have Usage prints full text, so flag.PrintDefaults not needed.

	err := fs.Parse(args)
	if err != nil {
		if err == flag.ErrHelp {
			// flag package already printed usage via fs.Usage? Actually when -help is provided, flag returns ErrHelp and also prints usage.
			// Our fs.Usage prints checkHelpText. The flag package would have printed usage before returning ErrHelp.
			// But we set fs.Usage to print checkHelpText, so duplicate. However we need to ensure exactly one copy.
			// For check -help, expected output is checkHelpText + "\nparse args: flag: help requested\n" to stderr, exit 1
			// Let's do: flag's error handling already printed usage? Let's check.
			// In flag package, Parse with -help: it calls fs.Usage() and returns ErrHelp, but also prints "flag: help requested"? Actually flag package prints usage and returns ErrHelp, but does not print "flag: help requested" itself. The error is "flag: help requested".
			// Our handling for check -help should print Usage + parse args line.
			// So we need to print "parse args: flag: help requested" after usage.
			fmt.Fprintln(os.Stderr, "parse args: flag: help requested")
			os.Exit(1)
			return err
		}
		// For unknown flag, flag package already printed "flag provided but not defined: -X" and usage via fs.Usage
		// But our check expected output is: first line error, then usage, then "parse args: flag provided..."
		// However flag package's default error printing already does first line + usage. We need to ensure we add the last line.
		// Let's see what flag does: In flag.NFlag handling for unknown, it prints to output: "flag provided but not defined: -X\nUsage of ...\n ..." via Usage. It doesn't print the final "parse args: ..." line.
		// That final line is added by go-critic's check.go: they wrap flag parsing and then print "parse args: %v"
		// So we need to add it here.
		// But note: flag already printed the first error and usage, so we just need to print the final line.

		// err is like "flag provided but not defined: -unknownFlag"
		fmt.Fprintf(os.Stderr, "parse args: %v\n", err)
		os.Exit(1)
		return err
	}

