func checkSloppyLen(fset *token.FileSet, file *ast.File) []struct{Pos token.Position; Message string} {
	var res []struct{Pos token.Position; Message string}
	ast.Inspect(file, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		if bin.Op != token.LEQ && bin.Op != token.GEQ && bin.Op != token.LSS && bin.Op != token.GTR && bin.Op != token.EQL && bin.Op != token.NEQ {
			return true
		}
		// Check left is len call
		call, ok := bin.X.(*ast.CallExpr)
		if !ok {
			// also check bin.Y is len?
			call, ok = bin.Y.(*ast.CallExpr)
			if !ok {
				return true
			}
		}
		if ident, ok := call.Fun.(*ast.Ident); ok && ident.Name == "len" {
			// Check if compared to 0
			other := bin.Y
			if call == bin.X {
				other = bin.Y
			} else {
				other = bin.X
			}
			if bl, ok := other.(*ast.BasicLit); ok && bl.Value == "0" {
				pos := fset.Position(bin.Pos())
				// Message: "len(arr) <= 0 can be len(arr) == 0" etc
				// For <=0, suggest ==0
				msg := fmt.Sprintf("len(arr) %s 0 can be len(arr) == 0", bin.Op.String())
				// Try to get actual len arg
				if len(call.Args) > 0 {
					argStr := printExpr(call.Args[0])
					msg = fmt.Sprintf("len(%s) %s 0 can be len(%s) == 0", argStr, bin.Op.String(), argStr)
				}
				res = append(res, struct{Pos token.Position; Message string}{Pos: pos, Message: msg})
			}
		}
		return true
	})
	return res
}

